{"implementation":"def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    n = len(nodes)
    edges = []
    for a,b,d in dists:
        if a > b:
            a, b = b, a
        w = max(core[a], core[b], d)
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total}
"}

